    "hook_moment": {"event_id": "E030-061", "what": "Elder Nobleman: \"She goes before the magistrate tomorrow.\""},
    "cliffhanger": {"event_id": "E031-009", "what": "Catherine enters the dungeon with a hot poker: \"The great Lady Juliana Ashcroft.\""},
    "stranger_question": "What will they do to her in that cell with a hot poker?",
    "why": "Starts on the death-sentence deadline, cuts to her chained in the flooded dungeon, then the next episode opens with her torturer entering—pure dread.",
    "funnel": "payoff",
    "safety": {"level": "mild", "reason": "Chained imprisonment shown; hot poker threat implies branding/torture."}
  }
